import json,os
demo={"input":[[6,5,5],[5,1,7],[4,5,2]],"output":[[6,6,5,5,5],[6,6,5,5,5],[5,5,1,7,7],[4,4,5,2,2],[4,4,5,2,2]]}
def transform(g):
    rs=[2 if i%2==0 else 1 for i in range(len(g))]
    cs=[2 if j%2==0 else 1 for j in range(len(g[0]))]
    out=[]
    for i,row in enumerate(g):
        block=[]
        for j,v in enumerate(row):
            block += [v]*cs[j]
        for _ in range(rs[i]): out.append([x for x in block])
    return out
